'use strict';

var valid = [];

// Format string with a placeholder...
var test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format( \'%s\', \'foo\' );'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'throw new Error( format( \'invalid argument. Must provide a string. Value: `%s`.\', \'foo\' ) );'
	].join( '\n' )
};
valid.push( test );

// Escaped percent sign with a placeholder...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format( \'%d%%\', 10 );'
	].join( '\n' )
};
valid.push( test );

// Non-literal format string...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = \'hello\';',
		'var out = format( str );'
	].join( '\n' )
};
valid.push( test );

// Calls via `#.call` and `#.apply`...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format.call( null, \'hello\' );'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'var str = format.apply( null, [ \'hello\' ] );'
	].join( '\n' )
};
valid.push( test );

// Shadowed symbols...
test = {
	'code': [
		'var format = require( \'@stdlib/string/format\' );',
		'',
		'function foo( format ) {',
		'  return format( \'hello\' );',
		'}'
	].join( '\n' )
};
valid.push( test );

// Unrelated symbols...
test = {
	'code': [
		'var format = require( \'d3-format\' );',
		'',
		'var str = format( \'hello\' );'
	].join( '\n' )
};
valid.push( test );

test = {
	'code': [
		'function format( str ) {',
		'  return str;',
		'}',
		'',
		'var str = format( \'hello\' );'
	].join( '\n' )
};
valid.push( test );


// EXPORTS //

module.exports = valid;
